sys_script_client.script:
function onSubmit() {
   // OnSubmit is for both Save and Update buttons
   //Type appropriate comment here, and begin script below
   //alert("Thank you for submitting a NeedIt request.");
   //global.UtilsString
    var getEmailAddr = new GlideAjax('x_1564615_utils.UtilsString');
    // Specify the getEmail method
    getEmailAddr.addParam('sysparm_name','validateEmailAddress');
    // Pass the Requested for sys_id
    getEmailAddr.addParam('sysparm_emailstr', g_form.getValue('u_requested_for_email'));
    // Send the request to the server
    getEmailAddr.getXML(populateEmailField);


    // When the response is back from the server
    function populateEmailField(response){
        // Extract the email address from the response, clear any value from the email field, 
        // set new value in the email field
        var isValid = response.responseXML.documentElement.getAttribute("answer");
		alert(isValid);
        // g_form.clearValue('u_requested_for_email');
      //  g_form.setValue('u_requested_for_email',emailFromScriptInclude);
    }

  return confirm('Please confirm if you want to proceed with the form submission');

}
